import{_ as e,o as s,c as a,a2 as d}from"./chunks/framework.CTWLzBUH.js";const u=JSON.parse('{"title":"Instructor walkthrough","description":"","frontmatter":{},"headers":[],"relativePath":"instructor/walkthrough.md","filePath":"instructor/walkthrough.md","lastUpdated":1790738794000}'),r={name:"instructor/walkthrough.md"};function i(o,t,n,h,l,p){return s(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="instructor-walkthrough" tabindex="-1">Instructor walkthrough <a class="header-anchor" href="#instructor-walkthrough" aria-label="Permalink to &quot;Instructor walkthrough&quot;">​</a></h1><p>How to run Trustville as a hands-on class, walking the modules in order, 1 to 16. Each module&#39;s own guide has the detailed steps under <em>Walk through it</em>; this page is what the person at the front of the room needs on top of that: what to prepare, who needs a partner, which steps need you, and where classes tend to get stuck.</p><h2 id="the-day-before" tabindex="-1">The day before <a class="header-anchor" href="#the-day-before" aria-label="Permalink to &quot;The day before&quot;">​</a></h2><ul><li><p>[ ] Seed the town so every stop has something on it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEPLOYER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cast</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wallet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> address</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --account</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> didlab-deployer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script/SeedDemo.s.sol</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rpc-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> didlab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --account</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> didlab-deployer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --sender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DEPLOYER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --legacy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --broadcast</span></span></code></pre></div><p>It posts a welcome notice, registers a product and opens a sealed-bid auction on it (48 hours of bidding), creates a town meeting with tickets, a charity campaign with three milestones, and a property. It leaves alone anything that needs two people or a role — those are better done live.</p></li><li><p>[ ] Check the faucet holds enough TRUST for the class, and note the course code.</p></li><li><p>[ ] Open the site in a fresh browser profile with a new wallet and do the warm-up yourself. If that fails, the class will fail the same way.</p></li></ul><h2 id="at-the-start-of-class" tabindex="-1">At the start of class <a class="header-anchor" href="#at-the-start-of-class" aria-label="Permalink to &quot;At the start of class&quot;">​</a></h2><ul><li>[ ] The block number in the site&#39;s header is moving.</li><li>[ ] The explorer and the faucet both load.</li><li>[ ] The course code is on the first slide, with the rule: <strong>never use a wallet that holds real money.</strong></li><li>[ ] A laptop running <code>npm run local</code> is ready as the fallback if the chain is down. It is a complete town on one machine; students can follow on the projector.</li></ul><h2 id="module-by-module" tabindex="-1">Module by module <a class="header-anchor" href="#module-by-module" aria-label="Permalink to &quot;Module by module&quot;">​</a></h2><p><strong>Pairs</strong> marks the modules where a student needs a classmate. <strong>You</strong> marks the steps only the instructor can do, because they need a role held by the town admin account — so connect that account in a separate browser profile before class. Put students in pairs from the start.</p><table tabindex="0"><thead><tr><th>#</th><th>Stop</th><th>Pairs</th><th>You</th><th>Where classes get stuck</th></tr></thead><tbody><tr><td>0</td><td>Notice Board (warm-up)</td><td></td><td></td><td>The wallet is on the wrong network; the site offers a <em>Switch</em> button</td></tr><tr><td>1</td><td>Town Hall · resident record</td><td></td><td></td><td>Nothing, usually. The first real contract call</td></tr><tr><td>2</td><td>Town Hall · passport</td><td></td><td></td><td>Forgetting to mint after registering</td></tr><tr><td>3</td><td>Bank · town token</td><td>Pairs for the transfer</td><td></td><td>Sending to their own address</td></tr><tr><td>4</td><td>Market · provenance</td><td>Pairs</td><td></td><td>Transferring custody of a product they do not hold</td></tr><tr><td>5</td><td>Market · escrow</td><td>Pairs</td><td>Resolve the disputed order</td><td>Two wallet prompts, <em>approve</em> then <em>pay</em>; rejecting the first looks like a failure</td></tr><tr><td>6</td><td>Market · sealed-bid auction</td><td>Pairs</td><td></td><td><strong>Losing the bid salt.</strong> It lives in the browser; say so before anyone bids</td></tr><tr><td>7</td><td>College · certificates</td><td>Pairs</td><td></td><td>Issuing a certificate to themselves, which the contract refuses</td></tr><tr><td>8</td><td>College · event tickets</td><td>Pairs</td><td></td><td>A start time already in the past</td></tr><tr><td>9</td><td>Housing · property deeds</td><td></td><td>Certify a deed (the admin holds <code>CERTIFIER_ROLE</code>)</td><td>Expecting certification to survive a transfer</td></tr><tr><td>10</td><td>Housing · rent escrow</td><td>Pairs</td><td>Resolve the disputed deposit</td><td>Waiting out the term and claim window: use short ones</td></tr><tr><td>11</td><td>Council · multisig treasury</td><td>Groups of three</td><td>You are one of the owners</td><td>Only owners can propose; decide the owners before class</td></tr><tr><td>12</td><td>Council · DAO governance</td><td>Groups</td><td></td><td>Wrapping tokens without delegating: zero votes</td></tr><tr><td>13</td><td>Charity</td><td>Groups</td><td>Approve or reject milestones (the admin holds <code>ARBITER_ROLE</code>)</td><td>Two wallet prompts per pledge, as in module 5</td></tr><tr><td>14</td><td>Insurer and oracle</td><td></td><td>The reporter services must be running</td><td>Buying cover for the current period, which is refused</td></tr><tr><td>15</td><td>Exchange</td><td></td><td></td><td>Large swaps and slippage: that is the lesson, not a bug</td></tr><tr><td>16</td><td>Privacy Lab</td><td>Needs a module 7 certificate</td><td></td><td>Posting from the account that enrolled; the page warns them</td></tr></tbody></table><h2 id="timing" tabindex="-1">Timing <a class="header-anchor" href="#timing" aria-label="Permalink to &quot;Timing&quot;">​</a></h2><p>Suggested split across weekly sessions, adjusting to how fast the room moves:</p><table tabindex="0"><thead><tr><th>Session</th><th>Modules</th></tr></thead><tbody><tr><td>1</td><td>Warm-up, 1–3</td></tr><tr><td>2</td><td>4–6</td></tr><tr><td>3</td><td>7–8, 9–10</td></tr><tr><td>4</td><td>11–12</td></tr><tr><td>5</td><td>13–14</td></tr><tr><td>6</td><td>15–16</td></tr></tbody></table><p>The map shows each student&#39;s progress from their passport stamps, and <em>Continue</em> takes them to their next unfinished module, so nobody needs to remember where they stopped.</p><h2 id="the-explorer-s-read-and-write-tabs" tabindex="-1">The explorer&#39;s Read and Write tabs <a class="header-anchor" href="#the-explorer-s-read-and-write-tabs" aria-label="Permalink to &quot;The explorer&#39;s Read and Write tabs&quot;">​</a></h2><p>Several guides ask students to call a function &quot;on the explorer&quot;. Those tabs exist only for <strong>verified</strong> contracts, and verification on explorer.didlab.org is waiting on its contract-verification service. Until then:</p><ul><li>Everything a student needs to <em>do</em> is on the site.</li><li>Events and transactions are readable on the explorer as they are.</li><li>To read a value directly, show it once from the front with <code>cast call</code>, for example <code>cast call &lt;passport&gt; &quot;passportOf(address)(uint256)&quot; &lt;student&gt; --rpc-url https://eth.didlab.org</code>.</li></ul><h2 id="after-class" tabindex="-1">After class <a class="header-anchor" href="#after-class" aria-label="Permalink to &quot;After class&quot;">​</a></h2><p>Nothing to reset. Students&#39; progress lives in their passports on chain, and the next session starts wherever each of them stopped.</p>`,18)])])}const k=e(r,[["render",i]]);export{u as __pageData,k as default};
